 14→const formatJsonWithPreservedWhitespace = (obj: any): string => {
 15→	return JSON.stringify(obj, null, 2)
 16→		.replace(/\\\\n/g, '\\n')
 17→		.replace(/\\n/g, '\n')
 18→		.replace(/\\\\t/g, '\\t')
 19→		.replace(/\\t/g, '\t');
 20→};
