 89→const CodeBlock = ({
 90→	content,
 91→	language = '',
 92→	isError = false,
 93→}: {
 94→	content: string;
 95→	language?: string;
 96→	isError?: boolean;
 97→}) => {
 98→	const [isTruncated, setIsTruncated] = useState(content.length > 500);
 99→	const codeRef = useRef<HTMLElement>(null);
100→
101→	useEffect(() => {
102→		if (codeRef.current && (globalThis as any).hljs) {
103→			(globalThis as any).hljs.highlightElement(codeRef.current);
104→		}
105→	}, [content, isTruncated]);
