 9→import cl from './Spinner.module.scss';
10→
11→
12→export type SpinnerName = keyof typeof icons;
13→export { cl as SpinnerClassNames };
14→
15→export type SpinnerProps = React.PropsWithChildren<ComponentProps<'span'> & {
16→  /**
17→   * If the spinner should be inline. Optional. Default: false.
18→   */
19→  inline?: undefined | boolean,
20→  
