 5→import variablesText from './variables.scss?raw';
 6→
 7→
 8→/*
 9→Some utilities to parse out information from `variables.scss` in order to use them in TypeScript code.
10→*/
11→
12→type Variables = Record<string, string>;
13→const variables = [...variablesText.matchAll(/\$(.+):(.+)(?:!default).*;/g)].reduce<Variables>(
14→  (variables, [match, variableName, variableValue]) => {
15→    if (!match.includes('/* ignore */') && variableName && variableValue) {
16→      variables[variableName.trim()] = variableValue.trim();
17→    }
18→    return variables;
19→  },
20→  {},
21→);
22→
23→type FontSizes = Record<string, { sizeQualifier: string, sizeInRem: number }>;
24→export const fontSizes = Object.entries(variables).reduce<FontSizes>(
25→  (fontSizes, [variableName, value]) => {
26→    const match = variableName.match(/^font-size-(.+)$/);
27→    if (!match) { return fontSizes; }
28→    
29→    const [_, sizeQualifier] = match;
30→    if (typeof sizeQualifier === 'undefined') { throw new Error(`Expected match`); }
31→    
32→    const sizeMatches = value.match(/math\.div\((\d+), (\d+)\)/);
33→    if (!sizeMatches) { throw new Error(`Unable to parse size: ${value}`); }
34→    
35→    fontSizes[variableName] = {
36→      sizeQualifier,
37→      sizeInRem: Number(sizeMatches[1]) / Number(sizeMatches[2]),
38→    };
39→    return fontSizes;
40→  },
41→  {},
42→);
