158→            }
159→          </div>
160→          
161→          <div className={cx(cl['bk-banner__actions'])}>
162→            {actions}
163→            
164→            {showCloseAction &&
165→              <ActionIcon
166→                icon="cross"
167→                label="Close banner"
168→                tooltip={null}
169→                className={cx(cl['bk-banner__action-close'])}
170→                onPress={onClose}
