  4→
  5→import * as React from 'react';
  6→import { classNames as cx, type ClassNameArgument, type ComponentProps } from '../../../util/componentUtil.ts';
  7→import { useScroller } from '../../../layouts/util/Scroller.tsx';
  8→
  9→import cl from './Tabs.module.scss';
 10→
 11→
 12→export { cl as TabsClassNames };
 13→
 14→export type TabKey = string;
 15→
 16→export type TabProps = ComponentProps<'div'> & {
 17→  /** A unique identifier for this tab. */
 18→  tabKey: string,
 19→  /** The contents of the tab, when active. */
 20→  children?: undefined | React.ReactNode,
 21→  /** A render prop to render the tab. Overrides `children`, if set. */
 22→  render?: undefined | (() => React.ReactNode),
 23→  /** The title of this tab, to be shown in the tab trigger button. */
 24→  title: React.ReactNode,
 25→  /** Whether to hide this tab. If true, the tab trigger is not rendered at all. */
 26→  hide?: undefined | boolean,
 27→  /** A class name to set on the tab trigger button. */
 28→  className?: undefined | ClassNameArgument,
 29→  /** A class name to set on the tab panel content. */
 30→  contentClassName?: undefined | ClassNameArgument,
 31→  /** Any additional props to pass to the tab trigger button. */
 32→  tabTriggerProps?: undefined | ComponentProps<'li'> & { [key: `data-${string}`]: string },
 33→};
 34→export const Tab = ({ children }: TabProps): React.ReactElement => {
 35→  return children as React.ReactElement;
 36→};
 37→type TabElement = React.ReactElement<TabProps, React.FunctionComponent<typeof Tab>>;
 38→
 39→export type TabsProps = ComponentProps<'div'> & {
 40→  /** Whether this component should be unstyled. */
 41→  unstyled?: undefined | boolean,
 42→
 43→  /** Active key of tab. */
 44→  activeKey?: undefined | string,
 45→
 46→   /** The orientation of the tabs, either vertical or horizontal. Default: `"horizontal"`. */
 47→  orientation?: undefined | 'horizontal' | 'vertical',
 48→
 49→  /** Which visual variant to use. Default: 'primary'. */
 50→  variant?: undefined | 'primary' | 'secondary',
 51→
 52→  /** Callback executed when active tab is changed. */
 53→  onSwitch: (tabKey: TabKey) => void,
 54→};
 55→/**
 56→ * A tab component
 57→ */
 58→export const Tabs = (props: TabsProps) => {
 59→  const {
 60→    unstyled = false,
 61→    variant = 'primary',
 62→    orientation = 'horizontal',
 63→    activeKey,
 64→    children,
 65→    onSwitch,
 66→    ...propsRest
 67→  } = props;
 68→  const scrollerProps = useScroller();
 69→
 70→  // Select the activeKey tab among the given list of tabs
 71→  const getActiveTab = (tabs: Array<TabElement>) => {
 72→    const activeTabs = tabs.filter(child => child.props.tabKey === activeKey);
 73→    
 74→    if (activeTabs.length === 0) { return null; }
 75→    if (activeTabs.length > 1) { throw new TypeError(`Ambiguous active tab`); }
 76→    
 77→    return activeTabs[0];
 78→  };
 79→  
 80→  type ActiveTabProps = Omit<TabProps, 'children' | 'tabKey' | 'title' | 'hide' | 'render'>;
 81→  const getActiveTabProps = (tab: TabElement): ActiveTabProps => {
 82→    const { children, tabKey, title, hide, render, tabTriggerProps, ...tabProps } = tab.props;
 83→    return tabProps;
 84→  };
 85→  
 86→  const renderActive = (tab: TabElement) => {
 87→    let tabElement: React.ReactNode;
 88→    if (typeof tab.props.render === 'function') {
 89→      tabElement = tab.props.render();
 90→    } else {
 91→      tabElement = tab.props.children;
 92→    }
 93→    
 94→    return tabElement;
 95→  };
 96→  
 97→  // FIXME: this throws an error in Chromatic, since `child.type` is `undefined`
 98→  // React.Children.forEach(children, (child: React.ReactNode) => {
 99→  //   if (!React.isValidElement(child) || child?.type?.name !== 'Tab') {
100→  //     throw new TypeError(`Expected only children of type Tab, received ${child}: ${JSON.stringify(child?.type)}`);
101→  //   }
102→  // });
103→  
104→  const tabs = React.Children.toArray(children) as Array<TabElement>;
105→  const activeTab = getActiveTab(tabs);
106→  const activeTabProps: null | ActiveTabProps = (activeTab && getActiveTabProps(activeTab)) ?? null;
107→  
108→  return (
109→    <div
110→      {...propsRest}
111→      className={cx(
112→        'bk',
113→        [cl[`bk-tabs--${variant}`]],
114→        [cl[`bk-tabs--${orientation}`]],
115→        { [cl['bk-tabs']]: !unstyled },
116→        propsRest.className,
117→      )}
118→    >
119→      <ul
120→        {...scrollerProps}
121→        className={cx(
122→          cl['bk-tabs__switcher'],
123→          scrollerProps.className
124→        )}
125→        role="tablist"
126→      >
127→        {tabs.map(tab => {
128→          const { tabKey, hide, tabTriggerProps } = tab.props;
129→          
130→          if (hide) { return null; }
131→          
132→          const isActive = tabKey === activeKey;
133→          
134→          return (
135→            <li
136→              key={tabKey}
137→              role="tab"
138→              tabIndex={0}
139→              aria-selected={isActive}
140→              data-tab={tabKey}
141→              {...tabTriggerProps}
142→              className={cx(cl['bk-tabs__switcher__tab'], tabTriggerProps?.className)}
143→              onClick={() => { onSwitch(tab.props.tabKey); }} // FIXME: add a Button and use that instead
144→            >
145→              <span>{tab.props.title}</span>
146→              {/* Hidden duplicated title, used to prevent layout shifts on hover. */}
147→              <span aria-hidden className={cx(cl['bk-tabs__switcher__tab__hover-placeholder'])}>{tab.props.title}</span>
148→            </li>
149→          );
150→        })}
151→      </ul>
152→      
153→      {activeTab &&
154→        <div
155→          role="tabpanel"
156→          {...(activeTabProps ?? {})}
157→          className={cx(
158→            cl['bk-tabs__tab-content'],
159→            activeTabProps?.contentClassName,
160→            activeTabProps?.className
161→          )}
162→        >
163→          {renderActive(activeTab)}
164→        </div>
165→      }
166→    </div>
167→  );
168→};
