 4→
 5→import * as React from 'react';
 6→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
 7→
 8→import { type DisclosureProps, Disclosure } from '../Disclosure/Disclosure.tsx';
 9→
10→import cl from './Accordion.module.scss';
11→
12→
13→export { cl as AccordionClassNames };
14→
15→type AccordionContext = { name?: undefined | string };
16→const AccordionContext = React.createContext<AccordionContext>({});
17→
18→type AccordionItemProps = Omit<DisclosureProps, 'name'>;
19→const AccordionItem = (props: AccordionItemProps) => {
20→  const context = React.use(AccordionContext);
21→  return (
22→    <Disclosure
23→      {...props}
24→      name={context.name}
25→      className={cx(cl['bk-accordion__item'], props.className)}
26→    />
27→  );
28→};
29→
30→export type AccordionProps = React.PropsWithChildren<ComponentProps<'div'> & {
31→  /** Whether this component should be unstyled. */
32→  unstyled?: undefined | boolean,
33→  
34→  /** If true, only one accordion may be open at a given time */
35→  exclusive?: undefined | boolean,
36→}>;
37→/**
38→ * Accordion component: a sequence of disclosure components that can be opened individually (exclusive by default).
39→ */
40→export const Accordion = Object.assign(
41→  (props: AccordionProps) => {
42→    const { unstyled = false, exclusive = true, ...propsRest } = props;
43→    
44→    const name = `bk-accordion-${React.useId()}`;
45→    const context: AccordionContext = React.useMemo(() => {
46→      if (exclusive) {
47→        return { name };
48→      }
49→      return {};
50→    }, [exclusive, name]);
51→    
52→    return (
53→      <AccordionContext value={context}>
54→        <div
55→          {...propsRest}
56→          className={cx({
57→            bk: true,
58→            [cl['bk-accordion']]: !unstyled,
59→          }, propsRest.className)}
60→        />
61→      </AccordionContext>
62→    );
63→  },
64→  { Item: AccordionItem },
65→);
66→

