import type { Meta, StoryObj } from '@storybook/react-vite';
import { Dialog } from './Dialog.tsx';

const meta = {
  title: 'AI Generated/Complex/Dialog',
  component: Dialog,
} satisfies Meta<typeof Dialog>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    title: 'Confirm Action',
    children: 'Are you sure you want to proceed with this action?',
  },
};

export const Loading: Story = {
  args: {
    title: 'Processing',
    state: 'loading',
    children: 'Please wait while we process your request...',
  },
};

import type { Meta, StoryObj } from '@storybook/react-vite';
import { Accordion } from './Accordion.tsx';

const meta = {
  title: 'AI Generated/Complex/Accordion',
  component: Accordion,
} satisfies Meta<typeof Accordion>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Exclusive: Story = {
  render: () => (
    <Accordion>
      <Accordion.Item title="Section 1">Content for section 1</Accordion.Item>
      <Accordion.Item title="Section 2">Content for section 2</Accordion.Item>
      <Accordion.Item title="Section 3">Content for section 3</Accordion.Item>
    </Accordion>
  ),
};

export const NonExclusive: Story = {
  render: () => (
    <Accordion exclusive={false}>
      <Accordion.Item title="Section A">Content for section A</Accordion.Item>
      <Accordion.Item title="Section B">Content for section B</Accordion.Item>
    </Accordion>
  ),
};

import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { Stepper } from './Stepper.tsx';

const meta = {
  title: 'AI Generated/Complex/Stepper',
  component: Stepper,
} satisfies Meta<typeof Stepper>;

export default meta;
type Story = StoryObj<typeof meta>;

const steps = [
  { stepKey: 'step1', title: 'Account Setup' },
  { stepKey: 'step2', title: 'Configuration' },
  { stepKey: 'step3', title: 'Review' },
];

export const Vertical: Story = {
  render: () => {
    const [activeKey, setActiveKey] = useState('step1');
    return (
      <Stepper steps={steps} activeKey={activeKey} onSwitch={setActiveKey} />
    );
  },
};

export const Horizontal: Story = {
  render: () => {
    const [activeKey, setActiveKey] = useState('step2');
    return (
      <Stepper
        steps={[
          { stepKey: 's1', title: 'Upload' },
          { stepKey: 's2', title: 'Process' },
          { stepKey: 's3', title: 'Done', isOptional: true },
        ]}
        activeKey={activeKey}
        onSwitch={setActiveKey}
        direction="horizontal"
      />
    );
  },
};
